-- Staging vector post-load (Supabase -> Aurora migration, staging cluster only).
-- Run AFTER the DMS full load has finished on vitana-aurora-staging, through
--   bash scripts/aws/staging-db-vector-postload.sh apply --cluster vitana-aurora-staging
-- which applies this file in ONE Data API transaction (staging-db-apply-migration.sh): every statement succeeds
-- or nothing is kept.
--
-- What it does, for the 13 pgvector columns that the pre-load staged as text so DMS could load them:
--   1. Refuses to start if the vector extension is missing, or if a view depends on one of the columns.
--   2. Copies every value that is not a complete vector of the right dimension (DMS truncates vectors on the
--      source read) into migration_audit.vector_incomplete, keyed by table, column and primary key. Nothing loaded
--      is discarded: the text stays recoverable there until the embedding backfill has replaced it.
--   3. Drops NOT NULL on a column only when it has such a value, because the type change turns it into NULL.
--   4. Casts the column back to vector(<dims>), and only while it is still text (re-runnable; a column that is
--      already vector is left alone).
--   5. Recreates the 9 vector indexes that Supabase has (IF NOT EXISTS).
--   6. Asserts the end state: every column is vector(<dims>) and every index exists and is valid. Otherwise it
--      raises, and the whole transaction rolls back.
-- It never truncates, deletes or reloads rows, changes no other column, and creates no foreign key (none to
-- auth.users). Primary keys and UUIDs are unchanged.
-- Column list, dimensions, primary keys and index definitions are the same as aurora-cutover-vector-postload.sql
-- and aurora-cutover-embedding-backfill.py (generated from the Supabase schema). products is out of scope, as it is there.
-- Next step: the embedding backfill (aurora-cutover-embedding-backfill.py --cluster vitana-aurora-staging).

-- 1. Guards. The extension's schema goes on this transaction's search_path, so `vector` resolves wherever it is installed.
DO $guard$ DECLARE s text; deps text; BEGIN SELECT n.nspname INTO s FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'vector'; IF s IS NULL THEN RAISE EXCEPTION 'staging vector post-load: the vector extension is not installed; nothing changed'; END IF; PERFORM set_config('search_path', 'public, ' || quote_ident(s), true); SELECT string_agg(DISTINCT v.oid::regclass::text || ' -> ' || c.relname || '.' || a.attname, ', ') INTO deps FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class JOIN pg_class c ON c.oid = d.refobjid JOIN pg_namespace cn ON cn.oid = c.relnamespace JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = d.refobjsubid WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass AND v.oid <> c.oid AND cn.nspname = 'public' AND (c.relname, a.attname) IN (('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')); IF deps IS NOT NULL THEN RAISE EXCEPTION 'staging vector post-load: views depend on vector columns (%); nothing changed', deps; END IF; END $guard$;

-- 2. Where incomplete values are kept, and the safe cast: NULL for anything that is not a complete '[n,n,...]' list of
--    exactly <dims> numbers. Each element is checked before the cast, so a truncated value can never make the cast fail.
CREATE SCHEMA IF NOT EXISTS migration_audit;
CREATE TABLE IF NOT EXISTS migration_audit.vector_incomplete (table_name text NOT NULL, column_name text NOT NULL, pk text NOT NULL, raw_text text NOT NULL, raw_length integer NOT NULL, stashed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (table_name, column_name, pk));
CREATE OR REPLACE FUNCTION migration_audit.try_vector(t text, dims integer) RETURNS vector LANGUAGE sql IMMUTABLE AS $fn$ SELECT CASE WHEN t LIKE '[%]' AND array_length(string_to_array(substr(t, 2, length(t) - 2), ','), 1) = dims AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(substr(t, 2, length(t) - 2), ',')) AS e WHERE btrim(e) !~ '^[-+]?([0-9]+[.]?[0-9]*|[.][0-9]+)([eE][-+]?[0-9]+)?$') THEN t::vector END $fn$;

-- 3 and 4. Keep the incomplete values, relax NOT NULL only where needed, cast back to vector. Only while the column is text.
DO $cast$ DECLARE r record; dtype text; nn boolean; kept bigint; BEGIN FOR r IN SELECT * FROM (VALUES ('ai_memory','embedding','id',768), ('calendar_events','embedding','id',1536), ('dev_agent_memory','embedding','id',1024), ('feedback_tickets','embedding','id',1536), ('mem_episodes','embedding','id',1536), ('mem_facts','embedding','id',1536), ('memory_embeddings','embedding','embedding_id',768), ('memory_facts','embedding','id',1024), ('memory_items','embedding','id',1024), ('user_intents','embedding','intent_id',1536), ('user_intents','embedding_v2','intent_id',1024), ('vtid_ledger','embedding','id',1536), ('vtid_ledger','embedding_v2','id',1024)) AS x(tbl, col, pk, dims) LOOP SELECT data_type, is_nullable = 'NO' INTO dtype, nn FROM information_schema.columns WHERE table_schema = 'public' AND table_name = r.tbl AND column_name = r.col; IF dtype IS NULL THEN RAISE EXCEPTION 'staging vector post-load: column public.%.% does not exist; nothing changed', r.tbl, r.col; END IF; IF dtype <> 'text' THEN RAISE NOTICE 'public.%.% is already %, skipped', r.tbl, r.col, dtype; CONTINUE; END IF; EXECUTE format('INSERT INTO migration_audit.vector_incomplete (table_name, column_name, pk, raw_text, raw_length) SELECT %L, %L, %I::text, %I, length(%I) FROM public.%I WHERE %I IS NOT NULL AND migration_audit.try_vector(%I, %s) IS NULL ON CONFLICT (table_name, column_name, pk) DO UPDATE SET raw_text = EXCLUDED.raw_text, raw_length = EXCLUDED.raw_length, stashed_at = now()', r.tbl, r.col, r.pk, r.col, r.col, r.tbl, r.col, r.col, r.dims); GET DIAGNOSTICS kept = ROW_COUNT; IF nn AND kept > 0 THEN EXECUTE format('ALTER TABLE public.%I ALTER COLUMN %I DROP NOT NULL', r.tbl, r.col); RAISE NOTICE 'public.%.%: NOT NULL dropped (% incomplete values); the backfill restores it', r.tbl, r.col, kept; END IF; EXECUTE format('ALTER TABLE public.%I ALTER COLUMN %I TYPE vector(%s) USING migration_audit.try_vector(%I, %s)', r.tbl, r.col, r.dims, r.col, r.dims); RAISE NOTICE 'public.%.%: vector(%), % incomplete values kept in migration_audit.vector_incomplete', r.tbl, r.col, r.dims, kept; END LOOP; END $cast$;

-- 5. The 9 vector indexes of Supabase (same definitions as aurora-cutover-vector-postload.sql). The IVFFlat ones are
--    rebuilt by the backfill once the embeddings are in (IVFFlat picks its centroids at build time).
CREATE INDEX IF NOT EXISTS ai_memory_embedding_idx ON public.ai_memory USING ivfflat (embedding vector_cosine_ops) WITH (lists='100');
CREATE INDEX IF NOT EXISTS dev_agent_memory_embedding_idx ON public.dev_agent_memory USING ivfflat (embedding vector_cosine_ops) WITH (lists='100');
CREATE INDEX IF NOT EXISTS mem_episodes_embedding_hnsw ON public.mem_episodes USING hnsw (embedding vector_cosine_ops) WITH (m='16', ef_construction='64');
CREATE INDEX IF NOT EXISTS mem_facts_embedding_hnsw ON public.mem_facts USING hnsw (embedding vector_cosine_ops) WITH (m='16', ef_construction='64');
CREATE INDEX IF NOT EXISTS idx_mem_emb_vector ON public.memory_embeddings USING ivfflat (embedding vector_cosine_ops) WITH (lists='100');
CREATE INDEX IF NOT EXISTS idx_memory_facts_embedding_hnsw ON public.memory_facts USING hnsw (embedding vector_cosine_ops) WITH (m='16', ef_construction='64');
CREATE INDEX IF NOT EXISTS idx_memory_items_embedding_hnsw ON public.memory_items USING hnsw (embedding vector_cosine_ops) WITH (m='16', ef_construction='64');
CREATE INDEX IF NOT EXISTS user_intents_embedding_hnsw_idx ON public.user_intents USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS idx_vtid_ledger_embedding_hnsw ON public.vtid_ledger USING hnsw (embedding vector_cosine_ops) WITH (m='16', ef_construction='64');

-- 6. End state, or roll everything back.
DO $assert$ DECLARE bad text; BEGIN SELECT string_agg(x.tbl || '.' || x.col || ' is ' || coalesce(format_type(a.atttypid, a.atttypmod), 'missing'), ', ') INTO bad FROM (VALUES ('ai_memory','embedding',768), ('calendar_events','embedding',1536), ('dev_agent_memory','embedding',1024), ('feedback_tickets','embedding',1536), ('mem_episodes','embedding',1536), ('mem_facts','embedding',1536), ('memory_embeddings','embedding',768), ('memory_facts','embedding',1024), ('memory_items','embedding',1024), ('user_intents','embedding',1536), ('user_intents','embedding_v2',1024), ('vtid_ledger','embedding',1536), ('vtid_ledger','embedding_v2',1024)) AS x(tbl, col, dims) LEFT JOIN pg_attribute a ON a.attrelid = to_regclass('public.' || x.tbl) AND a.attname = x.col AND NOT a.attisdropped WHERE a.attnum IS NULL OR format_type(a.atttypid, a.atttypmod) NOT IN ('vector(' || x.dims || ')', 'public.vector(' || x.dims || ')', 'extensions.vector(' || x.dims || ')'); IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging vector post-load: wrong column types (%); rolled back', bad; END IF; SELECT string_agg(i, ', ') INTO bad FROM unnest(ARRAY['ai_memory_embedding_idx','dev_agent_memory_embedding_idx','mem_episodes_embedding_hnsw','mem_facts_embedding_hnsw','idx_mem_emb_vector','idx_memory_facts_embedding_hnsw','idx_memory_items_embedding_hnsw','user_intents_embedding_hnsw_idx','idx_vtid_ledger_embedding_hnsw']) AS i WHERE NOT EXISTS (SELECT 1 FROM pg_index ix JOIN pg_class c ON c.oid = ix.indexrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = i AND ix.indisvalid); IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging vector post-load: missing or invalid indexes (%); rolled back', bad; END IF; END $assert$;
